<?php require __DIR__.'/config.php'; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0; $q=$pdo->prepare('SELECT * FROM students WHERE id=?');$q->execute([$id]);$s=$q->fetch();if(!$s){http_response_code(404);exit('Student not found.');}$q=$pdo->prepare('SELECT * FROM student_files WHERE student_id=? ORDER BY uploaded_at DESC');$q->execute([$id]);$files=$q->fetchAll(); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student profile</title><link rel="stylesheet" href="style.css"></head><body><main class="narrow"><a href="index.php">← All students</a><section class="card"><h1><?=h($s['name'])?></h1><p><b>Roll:</b> <?=h($s['roll_number'])?></p><p><b>Email:</b> <?=h($s['email'])?></p><p><b>Course:</b> <?=h($s['course'])?></p><a class="button" href="student.php?id=<?=$id?>">Edit profile / upload files</a></section><h2>Uploaded files</h2><section class="file-grid"><?php foreach($files as $f):?><article class="card"><?php if(str_starts_with($f['file_type'],'image/')):?><img class="preview" src="file.php?id=<?=(int)$f['id']?>" alt="Uploaded file preview"><?php else:?><div class="document-icon">PDF / Document</div><?php endif;?><p><?=h($f['original_name'])?></p><small><?=h($f['file_type'])?> · <?=number_format($f['file_size']/1024,1)?> KB</small><br><a href="file.php?id=<?=(int)$f['id']?>">Open / download</a></article><?php endforeach;?><?php if(!$files):?><p>No files uploaded.</p><?php endif;?></section></main></body></html>